package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// filterProducts handles GET /api/products?category=X&price_range=Y&tag=Z
func filterProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	priceRange := r.URL.Query().Get("price_range")
	tag := r.URL.Query().Get("tag")

	// Build base query with parameterized category filter
	clauses := []string{"1=1"}
	args := []interface{}{}
	argIdx := 1

	if category != "" {
		clauses = append(clauses, fmt.Sprintf("p.category_id = $%d", argIdx))
		args = append(args, category)
		argIdx++
	}

	// Price range uses a predefined mapping - safe
	switch priceRange {
	case "low":
		clauses = append(clauses, "p.price < 25.00")
	case "mid":
		clauses = append(clauses, "p.price BETWEEN 25.00 AND 100.00")
	case "high":
		clauses = append(clauses, "p.price > 100.00")
	}

	// Tag filter - joins against tags table using array containment
	// Developer note: tags are user-defined strings, using array syntax for flexibility
	tagFilter := ""
	if tag != "" {
		// Construct array literal for ANY() operator
		tags := strings.Split(tag, ",")
		quotedTags := make([]string, len(tags))
		for i, t := range tags {
			// Strip obvious dangerous chars but allow apostrophes in tag names like "women's"
			t = strings.ReplaceAll(t, ";", "")
			t = strings.ReplaceAll(t, "--", "")
			quotedTags[i] = fmt.Sprintf("'%s'", t)
		}
		tagFilter = fmt.Sprintf(" AND p.id IN (SELECT pt.product_id FROM product_tags pt JOIN tags t ON t.id = pt.tag_id WHERE t.name IN (%s))", strings.Join(quotedTags, ","))
	}

	query := fmt.Sprintf("SELECT p.id, p.name, p.price, p.sku FROM products p WHERE %s%s ORDER BY p.name LIMIT 50",
		strings.Join(clauses, " AND "), tagFilter)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck is used by the load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", filterProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
